@article{Gong_Yue_Xu_2025, title={An Optimal Transport-based Latent Mixer for Robust Multi-modal Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33849}, DOI={10.1609/aaai.v39i16.33849}, abstractNote={Multi-modal learning aims to learn predictive models based on the data from different modalities. However, due to the requirement of data security and privacy protection, real-world multi-modal data are often scattered to different agents and cannot be shared across the agents, which limits the application of existing multi-modal learning methods.
To achieve robust multi-modal learning in such a challenging scenario, we propose a novel optimal transport-based mixer (OTM), which works as an effective latent code alignment and augmentation method for unaligned and distributed multi-modal data. In particular, we train a Wasserstein autoencoder (WAE) for each agent, which encodes its single modal samples in a latent space. Through a central server, the proposed OTM computes a stochastic fused Gromov-Wasserstein barycenter (FGWB) to mix different modalities’ latent codes, so that each agent applies the barycenter to reconstruct its samples.
This method neither requires well-aligned multi-modal data nor assumes the data to share the same latent distribution, and each agent can learn a specific model based on multi-modal data while achieving inference based on its local modality. Experiments on multi-modal clustering and classification demonstrate that the models learned with the OTM method outperform the corresponding baselines.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gong, Fengjiiao and Yue, Angxiao and Xu, Hongteng}, year={2025}, month={Apr.}, pages={16826-16834} }

@article{Mishra_Saha_Zhao_Hernandez-Cruz_Patey_Papageorghiou_Noble_2025, title={MCAT: Visual Query-Based Localization of Standard Anatomical Clips in Fetal Ultrasound Videos Using Multi-Tier Class-Aware Token Transformer}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35047}, DOI={10.1609/aaai.v39i27.35047}, abstractNote={Accurate standard plane acquisition in fetal ultrasound (US) videos is crucial for fetal growth assessment, anomaly detection, and adherence to clinical guidelines. However, manually selecting standard frames is time-consuming and prone to intra- and inter-sonographer variability. Existing methods primarily rely on image-based approaches that capture standard frames and then classify the input frames across different anatomies. This ignores the dynamic nature of video acquisition and its interpretation.
To address these challenges, we introduce Multi-Tier Class-Aware Token Transformer (MCAT); a visual query-based video clip localization (VQ-VCL) method to assist sonographers by enabling them to capture a quick US sweep. By then providing a visual query of the anatomy they wish to analyze, MCAT returns the video clip containing the standard frames for that anatomy, facilitating thorough screening for potential anomalies.
We evaluate MCAT on two ultrasound video datasets and a natural image VQ-VCL dataset based on Ego4D. Our model outperforms state-of-the-art methods by 10% and 13% mtIoU on the ultrasound datasets and by 5.35% mtIoU on the Ego4D dataset, using 96% fewer tokens.
MCAT’s efficiency and accuracy have significant potential implications for public health, especially in low- and middle-income countries (LMICs), where it may enhance prenatal care by streamlining standard plane acquisition, simplifying US based screening, diagnosis and allowing sonographers to examine more patients.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mishra, Divyanshu and Saha, Pramit and Zhao, He and Hernandez-Cruz, Netzahualcoyotl and Patey, Olga and Papageorghiou, Aris and Noble, J. Alison}, year={2025}, month={Apr.}, pages={28267-28275} }

@article{Li_Guo_Qi_Li_Shi_2025, title={Text and Image Are Mutually Beneficial: Enhancing Training-Free Few-Shot Classification with CLIP}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32534}, DOI={10.1609/aaai.v39i5.32534}, abstractNote={Contrastive Language-Image Pretraining (CLIP) has been widely used in vision tasks. Notably, CLIP has demonstrated promising performance in few-shot learning (FSL).
However, existing CLIP-based methods in training-free FSL (i.e., without the requirement of additional training) mainly learn different modalities independently, leading to two essential issues: 1) severe anomalous match in image modality; 2) varying quality of generated text prompts.
To address these issues, we build a mutual guidance mechanism, that introduces an Image-Guided-Text (IGT) component to rectify varying quality of text prompts through image representations, and a Text-Guided-Image (TGI) component to mitigate the anomalous match of image modality through text representations.
By integrating IGT and TGI, we adopt a perspective of Text-Image Mutual guidance Optimization, proposing TIMO.
Extensive experiments show that TIMO significantly outperforms the state-of-the-art (SOTA) training-free method. Additionally, by exploring the extent of mutual guidance, we propose an enhanced variant, TIMO-S, which even surpasses the best training-required methods by 0.33% with approximately ×100 less time cost.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Yayuan and Guo, Jintao and Qi, Lei and Li, Wenbin and Shi, Yinghuan}, year={2025}, month={Apr.}, pages={5039-5047} }
